s='''def transform(grid):
    n=len(grid)
    # Expand each marked diagonal across its full anti-diagonal.
    seeds={}
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v:
                seeds[r+c]=v
    out=[[0]*n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if r+c in seeds: out[r][c]=seeds[r+c]
    return out
'''
